CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','writer') NOT NULL DEFAULT 'writer',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE tags (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,filename VARCHAR(255) NOT NULL UNIQUE,original_name VARCHAR(255) NOT NULL,mime VARCHAR(40) NOT NULL,size INT UNSIGNED NOT NULL,width INT UNSIGNED NOT NULL,height INT UNSIGNED NOT NULL,alt_text VARCHAR(255),caption VARCHAR(255),credit VARCHAR(255),uploaded_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_media_user FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE posts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,author_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,featured_media_id BIGINT UNSIGNED NULL,title VARCHAR(220) NOT NULL,slug VARCHAR(240) NOT NULL UNIQUE,excerpt TEXT NOT NULL,body MEDIUMTEXT NOT NULL,image_alt VARCHAR(255),image_credit VARCHAR(255),source_url VARCHAR(1000),meta_title VARCHAR(220),meta_description VARCHAR(320),status ENUM('draft','pending','published','archived') NOT NULL DEFAULT 'draft',is_featured TINYINT(1) NOT NULL DEFAULT 0,is_editor_pick TINYINT(1) NOT NULL DEFAULT 0,published_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_public(status,published_at,id),INDEX idx_author(author_id,status),CONSTRAINT fk_post_author FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_post_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT,CONSTRAINT fk_post_media FOREIGN KEY(featured_media_id) REFERENCES media(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE post_tags (post_id BIGINT UNSIGNED NOT NULL,tag_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(post_id,tag_id),FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE,FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE pages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,slug VARCHAR(160) NOT NULL UNIQUE,body MEDIUMTEXT NOT NULL,status ENUM('draft','published') DEFAULT 'draft',meta_description VARCHAR(320),updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE settings (`key` VARCHAR(100) PRIMARY KEY,value TEXT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE slug_redirects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,old_slug VARCHAR(240) NOT NULL UNIQUE,post_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,identifier_hash CHAR(64) NOT NULL,ip_hash CHAR(64) NOT NULL,succeeded TINYINT(1) NOT NULL DEFAULT 0,attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_attempt(identifier_hash,ip_hash,attempted_at)) ENGINE=InnoDB;
